/* An accessible spatial directory: real destinations, keyboard navigation, no XR hardware required. */
(()=>{
 const destinations=[['academy','Academy','Understand the research process','book','01'],['journey','Research journey','See your progress and next milestone','layers','02'],['toolkit','Toolkit','Find templates for your next task','file','03'],['notebook','Idea notebook','Capture observations and questions','notebook','04'],['notebook/draft','Proposal studio','Review your assembled working draft','edit','05'],['seminars','Workshops','Follow a focused session plan','people','06']];
 const trigger=document.createElement('button');trigger.className='explore-trigger';trigger.type='button';trigger.innerHTML=icon('grid')+'<span>Explore hub</span><kbd>Ctrl K</kbd>';trigger.setAttribute('aria-label','Explore hub — keyboard shortcut Control K');trigger.setAttribute('aria-haspopup','dialog');document.body.append(trigger);
 const dialog=document.createElement('dialog');dialog.id='space-navigator';dialog.setAttribute('aria-labelledby','space-title');dialog.innerHTML='<div class="space-top"><span>RESEARCH READY / YOUR CONNECTED WORKSPACE</span><button class="icon-button" aria-label="Close navigation">'+icon('close')+'</button></div><div class="space-intro"><p class="eyebrow">CHOOSE YOUR NEXT DESTINATION</p><h2 id="space-title">Where will your<br>curiosity take you?</h2><p>Each space has a purpose. Move freely between learning, writing, and planning your research.</p></div><div class="space-grid">'+destinations.map(([href,title,desc,symbol,n])=>'<a href="#'+href+'"><div class="space-card-art" aria-hidden="true"><i></i><i></i>'+icon(symbol)+'</div><span>'+n+' / RESEARCH SPACE</span><h3>'+title+'</h3><p>'+desc+'</p>'+icon('up')+'</a>').join('')+'</div><div class="space-foot"><span>Your work stays saved in this browser.</span><span>ESC TO CLOSE</span></div>';document.body.append(dialog);
 const open=()=>{if(!dialog.open)dialog.showModal()};trigger.onclick=open;dialog.querySelector('.space-top button').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();if(e.target.closest('a'))dialog.close()});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();dialog.open?dialog.close():open()}});
 let focus=false;
 function setup(){dialog.close();const lesson=document.querySelector('.lesson-main');document.body.classList.toggle('reading-focus',!!lesson&&focus);dialog.querySelectorAll('a').forEach(a=>{if(a.hash===location.hash)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(!lesson)return;const bar=document.createElement('div');bar.className='lesson-tools';bar.innerHTML='<span>'+icon('shield')+' Your draft saves as you write</span><button type="button" aria-pressed="'+focus+'">'+icon('book')+'<span>'+(focus?'Exit focus mode':'Focus reading')+'</span></button>';lesson.querySelector('.lesson-flow').before(bar);bar.querySelector('button').onclick=()=>{focus=!focus;document.body.classList.toggle('reading-focus',focus);const b=bar.querySelector('button');b.setAttribute('aria-pressed',String(focus));b.querySelector('span').textContent=focus?'Exit focus mode':'Focus reading';window.dispatchEvent(new Event('resize'))}}
 addEventListener('rrh:route',setup);setup();
})();
